#!/usr/bin/env bash
# install_gear_second.sh — Install gear-second command into PATH
# Run from: ~/projects/gear-second/
set -e

INSTALL_DIR="$HOME/.local/bin"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(dirname "$SCRIPT_DIR")"

echo "Installing gear-second from: $PROJECT_DIR"

# Create ~/.local/bin if it doesn't exist
mkdir -p "$INSTALL_DIR"

# Write the launcher script
cat > "$INSTALL_DIR/gear-second" << EOF
#!/usr/bin/env bash
# Gear Second launcher — auto-generated by install_gear_second.sh
exec python3 -m gear_second.cli "\$@"
EOF

# Write the alias
cat > "$INSTALL_DIR/gearsecond" << EOF
#!/usr/bin/env bash
exec python3 -m gear_second.cli "\$@"
EOF

chmod +x "$INSTALL_DIR/gear-second" "$INSTALL_DIR/gearsecond"

# Write the PYTHONPATH wrapper — ensures gear_second package is found
cat > "$INSTALL_DIR/gear-second" << EOF
#!/usr/bin/env bash
# Gear Second launcher — P51 Brain governed failover mode
export PYTHONPATH="${PROJECT_DIR}:\${PYTHONPATH}"
exec python3 -m gear_second.cli "\$@"
EOF

cat > "$INSTALL_DIR/gearsecond" << EOF
#!/usr/bin/env bash
export PYTHONPATH="${PROJECT_DIR}:\${PYTHONPATH}"
exec python3 -m gear_second.cli "\$@"
EOF

chmod +x "$INSTALL_DIR/gear-second" "$INSTALL_DIR/gearsecond"

# Check PATH
if [[ ":$PATH:" != *":$INSTALL_DIR:"* ]]; then
    echo ""
    echo "  NOTE: $INSTALL_DIR is not in your PATH."
    echo "  Add this to ~/.bashrc or ~/.zshrc:"
    echo "    export PATH=\"\$HOME/.local/bin:\$PATH\""
    echo ""
fi

echo "  gear-second installed at: $INSTALL_DIR/gear-second"
echo "  gearsecond installed at:  $INSTALL_DIR/gearsecond"
echo ""
echo "  Test with: gear-second status"
echo "  Or:        gear-second brief"
